class ResponseTlv : public Tlv
{
public:
    enum
    {
        kMinSize = 4, ///< Minimum size in bytes (Thread Specification).
        kMaxSize = 8, ///< Maximum size in bytes (Thread Specification).
    };

    /**
     * This method initializes the TLV.
     *
     */
    void Init(void)
    {
        SetType(kResponse);
        SetLength(sizeof(*this) - sizeof(Tlv));
    }

